// PREPARE PROFILE: turn the saved Airtable record into a clean profile for the 5 branches
// + MARKET CONFIG: which market we judge competitors in (DACH / EU / Global / North America)
const rec = $input.first().json;
const f = rec.fields || rec;            // works with Airtable output ({id, fields}) or a flat item

let raw;
try { raw = JSON.parse(f.profile_json || '{}'); }
catch (e) { throw new Error('profile_json is not valid JSON for run ' + f.run_id); }

// values only (what the branches reason about) + the evidence behind them (for citations later)
const profile = {};
const evidence = {};
for (const [field, obj] of Object.entries(raw)) {
  const v = obj ? obj.value : null;
  const empty = v === null || v === undefined || v === '' || (Array.isArray(v) && v.length === 0);
  profile[field] = empty ? null : v;
  if (!empty) {
    evidence[field] = obj.items
      ? obj.items.map(i => ({ item: i.item, quote: i.quote, source_url: i.source_url }))
      : [{ item: v, quote: obj.quote, source_url: obj.source_url }];
  }
}

const missing_fields = Object.keys(profile).filter(k => profile[k] === null);
const CORE = ['offering', 'problem_solved', 'buyer_industries'];
const missing_core = CORE.filter(k => profile[k] === null);

// ---------- MARKET CONFIG ----------
// key = exact option name in the form and in Airtable
const MARKETS = {
  'DACH':                     { label: 'DACH (Germany, Austria, Switzerland)', countries: ['DE', 'AT', 'CH'], languages: ['de', 'en'], local_language: 'German' },
  'Germany':                  { label: 'Germany', countries: ['DE'], languages: ['de', 'en'], local_language: 'German' },
  'Austria':                  { label: 'Austria', countries: ['AT'], languages: ['de', 'en'], local_language: 'German' },
  'Switzerland':              { label: 'Switzerland', countries: ['CH'], languages: ['de', 'fr', 'it', 'en'], local_language: 'German' },
  'UK & Ireland':             { label: 'UK & Ireland', countries: ['GB', 'IE'], languages: ['en'], local_language: '' },
  'France':                   { label: 'France', countries: ['FR'], languages: ['fr', 'en'], local_language: 'French' },
  'Benelux':                  { label: 'Benelux (Netherlands, Belgium, Luxembourg)', countries: ['NL', 'BE', 'LU'], languages: ['nl', 'fr', 'en'], local_language: 'Dutch' },
  'Nordics':                  { label: 'Nordics (Sweden, Denmark, Norway, Finland)', countries: ['SE', 'DK', 'NO', 'FI'], languages: ['sv', 'da', 'no', 'fi', 'en'], local_language: 'Swedish' },
  'Southern Europe':          { label: 'Southern Europe (Spain, Italy, Portugal)', countries: ['ES', 'IT', 'PT'], languages: ['es', 'it', 'pt', 'en'], local_language: 'Spanish' },
  'Central & Eastern Europe': { label: 'Central & Eastern Europe (Poland, Czechia, Romania, Hungary)', countries: ['PL', 'CZ', 'RO', 'HU'], languages: ['pl', 'cs', 'ro', 'hu', 'en'], local_language: 'Polish' },
  'EU':                       { label: 'Europe', countries: ['DE', 'FR', 'NL', 'GB', 'ES', 'IT'], languages: ['en', 'de', 'fr', 'nl', 'es', 'it'], local_language: '' },
  'North America':            { label: 'North America (US, Canada)', countries: ['US', 'CA'], languages: ['en'], local_language: '' },
  'United States':            { label: 'United States', countries: ['US'], languages: ['en'], local_language: '' },
  'Latin America':            { label: 'Latin America (Brazil, Mexico, Argentina, Colombia)', countries: ['BR', 'MX', 'AR', 'CO'], languages: ['es', 'pt', 'en'], local_language: 'Spanish' },
  'Middle East & Africa':     { label: 'Middle East & Africa (UAE, Saudi Arabia, Turkey, South Africa)', countries: ['AE', 'SA', 'TR', 'ZA'], languages: ['en', 'ar', 'tr'], local_language: '' },
  'India':                    { label: 'India', countries: ['IN'], languages: ['en'], local_language: '' },
  'Asia-Pacific':             { label: 'Asia-Pacific (Singapore, Australia, Japan, India)', countries: ['SG', 'AU', 'JP', 'IN'], languages: ['en', 'ja'], local_language: '' },
  'Global':                   { label: 'Global', countries: [], languages: [], local_language: '' }
};

// value from the form (Airtable single select can come as "DACH" or {name: "DACH"})
const pick = v => (v && typeof v === 'object' && v.name) ? v.name : (v || '');
let focus = String(pick(f.focus_market)).trim();
let inferred = false;
let inferred_from = '';

// no choice in the form -> infer from legal form, domain ending and stated regions
if (!MARKETS[focus]) {
  inferred = true;
  const name = String(profile.legal_name || profile.company_name || f.company_name || '');
  const dom = String(f.domain || '').toLowerCase();
  const regions = Array.isArray(profile.regions) ? profile.regions.join(' ') : String(profile.regions || '');
  if (/\b(gmbh|ag|ug|kg|se)\b/i.test(name) || /\.(de|at|ch)$/.test(dom) || /germany|deutschland|dach|austria|switzerland/i.test(regions)) {
    focus = 'DACH';
    inferred_from = 'legal form, domain or regions point to DACH';
  } else if (/europe|\beu\b|france|netherlands|spain|italy|united kingdom/i.test(regions)) {
    focus = 'EU';
    inferred_from = 'regions point to Europe';
  } else if (/united states|\busa?\b|north america|canada/i.test(regions)) {
    focus = 'North America';
    inferred_from = 'regions point to North America';
  } else {
    focus = 'Global';
    inferred_from = 'no market signal found';
  }
}

const m = MARKETS[focus];
// checkbox: true / false / empty. Empty means yes (show global players as a separate section)
const include_global = f.include_global === undefined || f.include_global === null || f.include_global === '' ? true : f.include_global === true;

const market = {
  focus: focus,
  label: m.label,
  countries: m.countries,
  languages: m.languages,
  local_language: m.local_language,
  include_global: include_global,
  inferred: inferred,
  inferred_from: inferred_from
};

// readable version for prompts: one line per known field, empty fields named explicitly, then the market line
const show = v => Array.isArray(v) ? v.join('; ') : String(v);
const marketLine = 'focus market: ' + m.label +
  (m.countries.length ? ' (countries ' + m.countries.join(', ') + ')' : '') +
  (inferred ? ' [inferred: ' + inferred_from + ']' : ' [chosen by user]') +
  (m.local_language ? '. Search in English and ' + m.local_language + '.' : '');

const profile_text = [
  ...Object.entries(profile).filter(([, v]) => v !== null).map(([k, v]) => k + ': ' + show(v)),
  'unknown (not stated by the company): ' + (missing_fields.join(', ') || 'none'),
  marketLine
].join('\n');

return [{ json: {
  record_id: rec.id || null,
  run_id: f.run_id,
  domain: f.domain,
  input_url: f.input_url,
  company_name: profile.company_name || f.company_name || f.domain,
  category: profile.category || null,
  profile,
  evidence,
  profile_text,
  missing_fields,
  missing_core,
  core_ok: missing_core.length === 0,
  market
} }];

// F1 - COLLECT RESULTS: merge all Perplexity searches into ONE list for the AI Agent
// (Mode: Run Once for All Items, so the AI Agent after it runs once, not 5 times)
const plan = $('F1 validate').first().json;
const ownDomain = String(plan.domain || '').toLowerCase();
const MAX_SNIPPET = 1200;
const jobs = plan.search_jobs || [];
// scope of the search that found a result: local (local language), market (English, in market), global (no country)
const scopeOf = qi => (jobs[qi] ? jobs[qi].scope + (jobs[qi].country ? ' ' + jobs[qi].country : '') : 'global');

const domainOf = url => {
  const m = String(url || '').match(/^https?:\/\/([^\/?#:]+)/i);
  return m ? m[1].toLowerCase().replace(/^www\./, '') : '';
};

// list pages name several competitors; vendor pages ARE a candidate company
const LIST_DOMAINS = ['capterra.', 'g2.com', 'softwareadvice.', 'getapp.', 'sourceforge.net', 'f6s.com', 'github.com', 'trustradius.com', 'gartner.com', 'saasworthy.com'];
const DROP_DOMAINS = ['marketintelo.com', 'dataintelo.com', 'marketsandmarkets.com', 'grandviewresearch.com', 'businesswire.com', 'prnewswire.com', 'linkedin.com', 'youtube.com', 'wikipedia.org'];

function kindOf(r, dom) {
  const t = (String(r.title || '') + ' ' + String(r.url || '')).toLowerCase();
  if (dom === ownDomain || dom.endsWith('.' + ownDomain)) return 'own';
  if (/\.(gov|europa\.eu)$/.test(dom) || dom.endsWith('europa.eu')) return 'drop';
  if (DROP_DOMAINS.some(d => dom === d || dom.endsWith('.' + d))) return 'drop';
  if (/market (size|research|report)|market-research|forecast report/.test(t)) return 'drop';
  if (LIST_DOMAINS.some(d => dom.includes(d))) return 'list';
  if (/\b(best|top \d+|top-\d+|alternatives|vs\.?|versus|compare|comparison|review)\b/.test(t)) return 'list';
  return 'vendor';
}

const byUrl = new Map();
const dropped = [];
$input.all().forEach((item, qi) => {
  for (const r of (item.json.results || [])) {
    if (!r || !r.url) continue;
    const key = String(r.url).toLowerCase().replace(/[?#].*$/, '').replace(/\/+$/, '');
    if (byUrl.has(key)) { const e = byUrl.get(key); e.found_by_queries.push(qi + 1); if (!e.found_via.includes(scopeOf(qi))) e.found_via.push(scopeOf(qi)); continue; }
    const dom = domainOf(r.url);
    const kind = kindOf(r, dom);
    if (kind === 'own' || kind === 'drop') { dropped.push({ url: r.url, reason: kind === 'own' ? 'own site' : 'report/news/official page' }); continue; }
    byUrl.set(key, {
      kind, domain: dom, title: String(r.title || '').trim(), url: r.url,
      snippet: String(r.snippet || '').replace(/\s+/g, ' ').trim().slice(0, MAX_SNIPPET),
      found_by_queries: [qi + 1],
      found_via: [scopeOf(qi)]
    });
  }
});

const results = [...byUrl.values()].map((r, i) => ({ id: 'R' + (i + 1), ...r }));
const results_text = results.map(r =>
  '[' + r.id + '] kind=' + r.kind + ' | domain=' + r.domain + ' | found via: ' + r.found_via.join(', ') + ' | ' + r.title + ' | ' + r.url + '\n' + r.snippet
).join('\n\n');

return [{ json: {
  run_id: plan.run_id,
  domain: plan.domain,
  company_name: plan.company_name,
  force: 'rivalry',
  rival_definition: plan.rival_definition,
  market: plan.market,
  result_count: results.length,
  vendor_pages: results.filter(r => r.kind === 'vendor').length,
  list_pages: results.filter(r => r.kind === 'list').length,
  results,
  results_text,
  dropped
} }];

// F1 VALIDATE rivalry PLAN: parse the plan, enforce the rules, build one search job per query (with country + language)
const prof = $('Prepare profile').first().json;
const raw = String($input.first().json.output || '').trim();

// parse (same repair as Check quotes: code fences and trailing commas)
const jsonText = raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1);
let plan;
try { plan = JSON.parse(jsonText); }
catch (e1) {
  try { plan = JSON.parse(jsonText.replace(/,\s*([}\]])/g, '$1')); }
  catch (e2) { throw new Error('AI Agent1 did not return valid JSON: ' + raw.slice(0, 300)); }
}

const issues = [];
const asList = v => (Array.isArray(v) ? v : []).map(x => String(x || '').trim()).filter(Boolean);

// 1. Queries: no own name or domain, no duplicates, sensible length, max 5
const own = [prof.company_name, prof.domain, String(prof.domain || '').split('.')[0]]
  .filter(Boolean).map(s => String(s).toLowerCase());
const seen = new Set();
const queries = [];
for (const q of asList(plan.perplexity_queries)) {
  const lq = q.toLowerCase();
  const hitsOwn = own.some(o => o.length >= 3 && new RegExp('\\b' + o.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b').test(lq));
  if (hitsOwn) { issues.push('dropped query with own name: ' + q); continue; }
  if (q.length < 10 || q.length > 200) { issues.push('dropped query (length): ' + q); continue; }
  if (seen.has(lq)) continue;
  seen.add(lq);
  queries.push(q);
}
if (queries.length > 4) { issues.push('cut English queries to 4'); queries.length = 4; }
if (queries.length < 2) throw new Error('Rivalry plan has fewer than 2 usable queries: ' + JSON.stringify(plan.perplexity_queries));

// 2. Company search filters
const cs = plan.company_search || {};
let min = Number.isFinite(cs.employee_min) ? cs.employee_min : null;
let max = Number.isFinite(cs.employee_max) ? cs.employee_max : null;
if (min !== null && max !== null && min > max) { [min, max] = [max, min]; issues.push('swapped employee_min/max'); }
const company_search = {
  keywords: asList(cs.keywords).slice(0, 5),
  industries: asList(cs.industries).slice(0, 3),
  employee_min: min,
  employee_max: max,
  countries: asList(cs.countries)
};
if (!company_search.keywords.length) throw new Error('Rivalry plan has no company_search keywords');

// 4. MARKET: countries and search jobs come from the focus market (form), not from profile.regions
const mk = prof.market || { focus: 'Global', label: 'Global', countries: [], languages: [], local_language: '', include_global: true };
const LANG_CODE = { German: 'de', French: 'fr', Dutch: 'nl', Swedish: 'sv', Spanish: 'es', Polish: 'pl', Italian: 'it', Portuguese: 'pt', Japanese: 'ja' };
const localCode = LANG_CODE[mk.local_language] || '';
const C = Array.isArray(mk.countries) ? mk.countries : [];
company_search.countries = C.slice();

// local-language queries (only when the market has a local language)
const local_queries = [];
if (localCode) {
  for (const q of asList(plan.local_queries)) {
    const lq = q.toLowerCase();
    const hitsOwn = own.some(o => o.length >= 3 && new RegExp('\\b' + o.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b').test(lq));
    if (hitsOwn) { issues.push('dropped local query with own name: ' + q); continue; }
    if (q.length < 6 || q.length > 200) { issues.push('dropped local query (length): ' + q); continue; }
    if (seen.has(lq)) continue;
    seen.add(lq);
    local_queries.push(q);
  }
  if (local_queries.length > 3) { issues.push('cut local queries to 3'); local_queries.length = 3; }
  if (!local_queries.length) issues.push('no usable ' + mk.local_language + ' queries from the plan');
}

// one item per search: English in the main market, local language rotated over the market countries,
// plus one global search (no country) when global players should be included
const search_jobs = [];
if (!C.length) {
  queries.forEach(q => search_jobs.push({ query: q, country: '', language_filter: '', scope: 'global' }));
} else {
  queries.forEach(q => search_jobs.push({ query: q, country: C[0], language_filter: (mk.languages || []).join(','), scope: 'market' }));
  local_queries.forEach((q, i) => search_jobs.push({ query: q, country: C[i % C.length], language_filter: localCode, scope: 'local' }));
  if (mk.include_global && queries.length) search_jobs.push({ query: queries[0], country: '', language_filter: '', scope: 'global' });
}

return [{ json: {
  run_id: prof.run_id,
  domain: prof.domain,
  company_name: prof.company_name,
  force: 'rivalry',
  rival_definition: String(plan.rival_definition || ''),
  category_keywords: asList(plan.category_keywords),
  perplexity_queries: queries,
  local_queries,
  search_jobs,
  market: mk,
  company_search,
  based_on: asList(plan.based_on),
  scope_note: String(plan.scope_note || ''),
  issues
} }];

// F1 CHECK: keep only companies whose evidence really appears in the search results
// Output: one item per verified competitor (ready for Merge 1)
const col = $('F1 collect results').first().json;
const out = $input.first().json;
const raw = String(out.output || out.text || '').trim();

const jsonText = raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1);
let parsed;
try { parsed = JSON.parse(jsonText); }
catch (e1) {
  try { parsed = JSON.parse(jsonText.replace(/,\s*([}\]])/g, '$1')); }
  catch (e2) { throw new Error('F1 extract did not return valid JSON (maybe cut off - check max tokens): ' + raw.slice(-200)); }
}

const norm = s => String(s || '').toLowerCase()
  .replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/[–—]/g, '-')
  .replace(/[*_#>`\[\]()|]/g, ' ').replace(/\s+/g, ' ').trim();
const coreName = s => norm(s).replace(/\.(com|ai|io|de|co|net)$/, '')
  .replace(/\b(technologies|technology|software|systems|inc|ltd|gmbh|group|logistics|solutions)\b/g, '').replace(/\s+/g, ' ').trim();

const results = {};
for (const r of col.results || []) results[r.id] = { ...r, text: norm(r.title + ' ' + r.snippet + ' ' + r.url) };
const knownDomains = new Set((col.results || []).map(r => r.domain));
const ownDomain = String(col.domain || '').toLowerCase();
const ownName = coreName(col.company_name);

// a quote may contain "..." where the model skipped words: every part must be found
const quoteFound = (quote, r) => {
  const parts = String(quote || '').split(/\.\.\.|…/).map(norm).filter(p => p.length >= 8);
  return parts.length > 0 && parts.every(p => r.text.includes(p));
};

const kept = [];
const failed = [];
for (const c of parsed.companies || []) {
  const name = String(c.name || '').trim();
  if (!name) continue;
  let domain = c.domain ? String(c.domain).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '') : null;

  if (domain && (domain === ownDomain || domain.endsWith('.' + ownDomain)) || coreName(name) === ownName) {
    failed.push({ name, reason: 'is the analysed company' }); continue;
  }
  // a claimed domain must belong to one of the search results; otherwise leave it for enrichment
  const domainNote = domain && !knownDomains.has(domain) ? 'domain not in results, cleared' : null;
  if (domainNote) domain = null;

  const cn = coreName(name);
  const goodEvidence = [];
  for (const ev of c.evidence || []) {
    const r = results[ev.result_id];
    if (!r) continue;
    if (!quoteFound(ev.quote, r)) continue;
    // the result must be about this company: its own domain, or the name appears in the result
    const aboutCompany = (domain && r.domain === domain) || (cn.length >= 3 && r.text.includes(cn));
    if (!aboutCompany) continue;
    goodEvidence.push({ result_id: ev.result_id, quote: ev.quote, url: r.url, kind: r.kind });
  }
  if (!goodEvidence.length) { failed.push({ name, reason: 'no evidence found in the results' }); continue; }

  kept.push({
    run_id: col.run_id,
    analysed_domain: col.domain,
    force: 'rivalry',
    tool: 'perplexity',
    name,
    domain,
    fit: c.fit === 'adjacent' ? 'adjacent' : 'direct',
    what_they_do: String(c.what_they_do || ''),
    evidence: goodEvidence,
    from_own_site: goodEvidence.some(e => e.kind === 'vendor' && domain && results[e.result_id].domain === domain),
    note: domainNote
  });
}

// nothing kept: return one status item so the reasons are visible (dedupe skips items without a name)
if (!kept.length) {
  return [{ json: {
    run_id: col.run_id,
    force: 'rivalry',
    status: 'no_candidates',
    ai_company_count: (parsed.companies || []).length,
    f1_failed: failed,
    f1_rejected_by_ai: parsed.rejected || []
  } }];
}
// the log (failed + rejected) goes on the first item only
return kept.map((k, i) => ({ json: i === 0 ? { ...k, f1_failed: failed, f1_rejected_by_ai: parsed.rejected || [] } : k }));

