const DROP_DOMAINS = ['marketintelo.com', 'dataintelo.com', 'marketsandmarkets.com', 'grandviewresearch.com', 'businesswire.com', 'prnewswire.com', 'linkedin.com', 'youtube.com', 'wikipedia.org'];

function kindOf(r, dom) {
  const t = (String(r.title || '') + ' ' + String(r.url || '')).toLowerCase();
  if (dom === ownDomain || dom.endsWith('.' + ownDomain)) return 'own';
  if (/\.(gov|europa\.eu)$/.test(dom) || dom.endsWith('europa.eu')) return 'drop';
  if (DROP_DOMAINS.some(d => dom === d || dom.endsWith('.' + d))) return 'drop';
  if (/market (size|research|report)|market-research|forecast report/.test(t)) return 'drop';
