const rootDomain = d => {
  if (!d) return null;
  const host = String(d).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[\/?#].*$/, '');
  const parts = host.split('.');
  const lastTwo = parts.slice(-2).join('.');
  return TWO_PART_TLDS.includes(lastTwo) ? parts.slice(-3).join('.') : lastTwo;
};
// cleaned name: "Trax Technologies" -> "trax", "Freehand.ai" -> "freehand"
const nameKey = n => String(n || '').toLowerCase()
  .replace(/\.(com|ai|io|de|co|net|app)\b/g, ' ')
  .replace(/[^a-z0-9 ]+/g, ' ')
  .replace(/\b(technologies|technology|software|systems|information|inc|ltd|llc|gmbh|ag|group|solutions|the)\b/g, ' ')
  .replace(/\s+/g, ' ').trim();

// 1. link hits that belong to the same company (union-find)
const parent = items.map((_, i) => i);
const find = i => (parent[i] === i ? i : (parent[i] = find(parent[i])));
const union = (a, b) => { parent[find(a)] = find(b); };
const byDomain = {}, byName = {};
items.forEach((it, i) => {
  const d = rootDomain(it.domain);
  const k = nameKey(it.name);
  if (d) { if (byDomain[d] !== undefined) union(i, byDomain[d]); else byDomain[d] = i; }
  if (k.length >= 3) { if (byName[k] !== undefined) union(i, byName[k]); else byName[k] = i; }
});

// 2. build one row per group
const groups = {};
items.forEach((it, i) => { const g = find(i); (groups[g] = groups[g] || []).push(it); });

const rows = Object.values(groups).map(hits => {
  hits.sort((a, b) => FORCE_ORDER.indexOf(a.force) - FORCE_ORDER.indexOf(b.force));
  const forces = FORCE_ORDER.filter(f => hits.some(h => h.force === f));
  const domains = [...new Set(hits.map(h => rootDomain(h.domain)).filter(Boolean))];
  const names = [...new Set(hits.map(h => h.name))];
  // display name: the shortest name that was seen (usually the brand)
  const name = names.slice().sort((a, b) => a.length - b.length)[0];

  const fit_by_force = {};
  for (const f of forces) fit_by_force[f] = hits.filter(h => h.force === f).some(h => h.fit === 'direct') ? 'direct' : 'adjacent';

  const seenQuote = new Set();
  const evidence = [];
  for (const h of hits) for (const e of h.evidence || []) {
    const key = String(e.quote).toLowerCase();
    if (seenQuote.has(key)) continue;
    seenQuote.add(key);
    evidence.push({ force: h.force, quote: e.quote, url: e.url, kind: e.kind });
  }
  const recent_moves = evidence.filter(e => e.force === 'new_entrant');

  return {
    run_id: hits[0].run_id,
    analysed_domain: hits[0].analysed_domain,
    name,
    other_names: names.filter(n => n !== name),
    domain: domains[0] || null,
    other_domains: domains.slice(1),
    forces,                                   // every force the company was found under
    force_count: forces.length,
    display_group: forces[0],                 // only for the report layout
    fit_by_force,
    any_direct: Object.values(fit_by_force).includes('direct'),
    what_they_do: hits[0].what_they_do,
    hits: hits.length,
    evidence,
    recent_moves,
    from_own_site: hits.some(h => h.from_own_site),
    needs_domain: domains.length === 0,       // Clay enrichment finds the domain later
    status: 'candidate'
  };
});

rows.sort((a, b) => b.force_count - a.force_count || b.hits - a.hits || a.name.localeCompare(b.name));

// Airtable-friendly text versions of the lists
const out = rows.map(r => ({
  ...r,
  forces_text: r.forces.join(', '),
  evidence_text: r.evidence.map(e => '[' + e.force + '] "' + e.quote + '" - ' + e.url).join('\n'),
  recent_moves_text: r.recent_moves.map(e => '"' + e.quote + '" - ' + e.url).join('\n'),
  other_names_text: r.other_names.join(', ')
}));

const summary = {
  hits_in: items.length,
  companies_out: out.length,
  merged: items.length - out.length,
  by_force: Object.fromEntries(FORCE_ORDER.map(f => [f, out.filter(r => r.forces.includes(f)).length])),
  found_by_2_or_more: out.filter(r => r.force_count >= 2).map(r => r.name),
  without_domain: out.filter(r => r.needs_domain).map(r => r.name)
};

return out.map((r, i) => ({ json: i === 0 ? { ...r, run_summary: summary } : r }));

let src;
try { src = $('Create a record1').item.json; }
catch (e) { src = $('Create a record1').all()[$itemIndex].json; }
const f = src.fields || {};
const o = $json.organization || null;
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const https = u => u ? String(u).replace(/^http:\/\//, 'https://') : undefined;
const day = d => d ? String(d).slice(0, 10) : undefined;

const out = { id: src.id, enriched: true };

if (!o || !o.name) {
  out.needs_domain = !f.domain;
  out.enrich_note = 'Apollo: no match';
  return { json: out };
}

// Name-only lookups: name must match AND industry + description must fit
if (!f.domain) {
  const a = norm(o.name), b = norm(f.name);
  const nameOk = a.includes(b) || b.includes(a);
  const INDUSTRIES = ['logistics & supply chain', 'computer software', 'information technology & services', 'internet', 'transportation/trucking/railroad', 'financial services'];
  const industryOk = INDUSTRIES.includes(String(o.industry || '').toLowerCase());
  const topicOk = industryOk && /freight|logistic|shipping|shipper|carrier|supply chain|tms/.test(String(o.short_description || '').toLowerCase());
  if (!nameOk || !topicOk) {
    out.needs_domain = true;
    out.enrich_note = `Name-only match rejected: Apollo found "${o.name}" (${o.industry || 'no industry'})`;
    return { json: out };
  }
  out.domain = o.primary_domain;
  out.enrich_note = 'Domain found by name, check once';
}

const dept = o.departmental_head_count || {};
const parent = (o.owned_by_organization && o.owned_by_organization.name)
  || (o.ultimate_parent_organization && o.ultimate_parent_organization.name);
const rounds = (o.funding_events || [])
  .map(e => [day(e.date), e.type, e.amount ? `${e.amount} ${e.currency || ''}`.trim() : null, e.investors ? `(${e.investors})` : null].filter(Boolean).join(' '))
  .join('\n');

Object.assign(out, {
  needs_domain: false,
  apollo_id: o.id,
  apollo_name: o.name,
  apollo_description: o.short_description,
  website_url: https(o.website_url),
  logo_url: o.logo_url,
  linkedin_url: https(o.linkedin_url),
  crunchbase_url: https(o.crunchbase_url),
  hq_country: o.country,
  hq_city: o.city,
  industry: o.industry,
  keywords_text: (o.keywords || []).join(', '),
  employees: o.estimated_num_employees,
  founded_year: o.founded_year,
  headcount_growth_6m: o.organization_headcount_six_month_growth,
  headcount_growth_12m: o.organization_headcount_twelve_month_growth,
  headcount_growth_24m: o.organization_headcount_twenty_four_month_growth,
  sales_headcount: dept.sales,
  engineering_headcount: dept.engineering,
  funding_total: o.total_funding_printed,
  funding_total_usd: o.total_funding,
  last_funding_stage: o.latest_funding_stage,
  last_funding_date: day(o.latest_funding_round_date),
  funding_rounds_text: rounds,
  revenue: o.organization_revenue_printed || o.annual_revenue_printed,
  parent_company: parent,
  public_ticker: o.publicly_traded_symbol,
});

for (const k of Object.keys(out)) if (out[k] === null || out[k] === undefined || out[k] === '') delete out[k];
return { json: out };

// JUDGE INPUT: one item per company with everything the judge may use (search evidence + Apollo data)
// Mode: Run Once for All Items. Connect: Code in JavaScript2 -> Judge input -> AI Agent2
const MAX_EVIDENCE = 8;     // quotes per company sent to the judge (keeps tokens low)
const MAX_DESC = 900;       // characters of the Apollo description
const MAX_KEYWORDS = 30;    // Apollo keywords
// fields that go on to Update record (the Apollo enrichment); everything else is dropped
const KEEP = ['id', 'enriched', 'needs_domain', 'enrich_note', 'domain', 'apollo_id', 'apollo_name', 'apollo_description',
  'website_url', 'logo_url', 'linkedin_url', 'crunchbase_url', 'hq_country', 'hq_city', 'industry', 'keywords_text',
  'employees', 'founded_year', 'headcount_growth_6m', 'headcount_growth_12m', 'headcount_growth_24m', 'sales_headcount',
  'engineering_headcount', 'funding_total', 'funding_total_usd', 'last_funding_stage', 'last_funding_date',
  'funding_rounds_text', 'revenue', 'parent_company', 'public_ticker'];

// the created Airtable rows hold name, forces and search evidence
// (test mode: if Create a record1 did not run, rows from an Airtable search are used directly)
const created = {};
try { for (const it of $('Create a record1').all()) created[it.json.id] = it.json.fields || {}; } catch (e) {}

// profile of the analysed company: from Prepare profile in a normal run, from TEST load profile in a test
let profile_text = '';
try { profile_text = $('Prepare profile').first().json.profile_text; } catch (e) {}
if (!profile_text) {
  try {
    const pr = $('TEST load profile').first().json;
    const pf = pr.fields || pr;
    const raw = JSON.parse(pf.profile_json || '{}');
    const show = v => Array.isArray(v) ? v.map(x => (x && typeof x === 'object') ? x.item : x).join('; ') : String(v);
    profile_text = Object.keys(raw)
      .filter(k => raw[k] && raw[k].value !== null && raw[k].value !== '' && !(Array.isArray(raw[k].value) && !raw[k].value.length))
      .map(k => k + ': ' + show(raw[k].value)).join('\n');
  } catch (e) {}
}
if (!profile_text) throw new Error('No company profile: run Prepare profile (normal run) or TEST load profile (test)');

const clip = (s, n) => {
  const t = String(s || '').replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n) + '...' : t;
};

return $input.all().map(i => {
  const a = i.json.fields ? Object.assign({ id: i.json.id }, i.json.fields) : i.json;
  const c = created[a.id] || a;
  const evidence = String(c.evidence_text || '').split('\n').map(s => s.trim()).filter(Boolean).slice(0, MAX_EVIDENCE);
  const keywords = String(a.keywords_text || '').split(',').map(s => s.trim()).filter(Boolean).slice(0, MAX_KEYWORDS).join(', ');

  const apolloLines = a.apollo_id ? [
    'Apollo name: ' + (a.apollo_name || ''),
    'Industry: ' + (a.industry || 'unknown'),
    'Employees: ' + (a.employees || 'unknown'),
    'HQ: ' + ([a.hq_city, a.hq_country].filter(Boolean).join(', ') || 'unknown'),
    'Description: ' + clip(a.apollo_description, MAX_DESC),
    'Keywords: ' + (keywords || 'none')
  ] : ['No company data found (' + (a.enrich_note || 'Apollo: no match') + '). Judge from the search evidence only.'];

  const judge_text = [
    'Name: ' + (c.name || a.apollo_name || ''),
    'Domain: ' + (a.domain || c.domain || 'unknown'),
    'Found under forces: ' + (c.forces_text || ''),
    'Summary from search: ' + clip(c.what_they_do, 400),
    '',
    'COMPANY DATA (Apollo)',
    ...apolloLines,
    '',
    'SEARCH EVIDENCE (quotes from web pages)',
    ...(evidence.length ? evidence : ['none'])
  ].join('\n');

  // pass on ONLY the record id and the enrichment fields; no old verdicts, scores or reasons travel with the item
  const out = {};
  for (const k of KEEP) if (a[k] !== undefined && a[k] !== null && a[k] !== '') out[k] = a[k];
  return { json: Object.assign(out, { name: c.name || a.apollo_name || '', forces_text: c.forces_text || '', profile_text, judge_text }) };
});

// PARSE VERDICT: pairs each judge answer with its company, checks the quote, builds the Airtable update
// Mode: Run Once for All Items. Connect: AI Agent2 -> Parse verdict -> Update record
const STRICT = true; // true: a "true" verdict with buyer "unclear" becomes "unsure"

const inputs = $('Judge input').all().map(i => i.json);
const answers = $input.all().map(i => i.json);
if (inputs.length !== answers.length) {
  throw new Error('Count mismatch: ' + inputs.length + ' companies vs ' + answers.length + ' judge answers');
}

const FORCES = ['rivalry', 'substitute', 'new_entrant'];
const TYPES = ['software', 'service', 'logistics_provider', 'consultancy', 'other'];

const norm = s => String(s || '').toLowerCase()
  .replace(/[‘’]/g, "'").replace(/[“”"]/g, '').replace(/[–—]/g, '-')
  .replace(/https?:\/\/\S+/g, ' ').replace(/[*_#>`\[\]()|\\]/g, ' ')
  .replace(/\s+/g, ' ').trim();

const parseJudge = raw => {
  const s = String(raw || '').replace(/```json|```/g, '').trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a < 0 || b < 0) return null;
  const txt = s.slice(a, b + 1);
  try { return JSON.parse(txt); } catch (e) {}
  try { return JSON.parse(txt.replace(/,\s*([}\]])/g, '$1')); } catch (e) {}
  return null;
};

const cleanVerdict = v => {
  const s = String(v).toLowerCase().trim();
  return ['true', 'false', 'unsure'].includes(s) ? s : 'unsure';
};

// the quote must appear in the facts the judge was given (Apollo data or search evidence)
const quoteOk = (quote, facts) => {
  const f = norm(facts);
  const parts = String(quote || '').split(/\.\.\.|…|\s-\s/).map(norm).filter(p => p.length >= 8);
  return parts.length > 0 && parts.every(p => f.includes(p));
};

return inputs.map((c, i) => {
  const parsed = parseJudge(answers[i].output || answers[i].text);
  // the judge rates all three forces, not only the ones the search found the company under
  const forces = FORCES;

  const verdicts = {};
  const reasons = [];
  let buyer = 'unclear';
  let business_type = 'other';
  let judge_quote = '';
  let segment_match = 'unclear';
  let segment_note = '';
  let job_focus = 'unknown';

  // output check: an empty or cut-off answer is NEVER turned into verdicts. The row stays "candidate"
  // and is marked, so it is visible and can be judged again (Stage 2.2 leaves it out of the scoring).
  if (!parsed || !Array.isArray(parsed.judgements) || !parsed.business_type) {
    const raw = String(answers[i].output || answers[i].text || '');
    const failed = Object.assign({}, c, {
      status: 'candidate',
      judge_reasons: 'JUDGE FAILED: answer ' + (raw ? 'cut off after ' + raw.length + ' characters' : 'empty') + '. Judge this company again.'
    });
    delete failed.judge_text;
    delete failed.profile_text;
    return { json: failed };
  }
  {
    const b = String(parsed.buyer_match || '').toLowerCase();
    buyer = ['yes', 'no', 'unclear'].includes(b) ? b : 'unclear';
    const t = String(parsed.business_type || '').toLowerCase();
    business_type = TYPES.includes(t) ? t : 'other';
    if (parsed.main_product) reasons.push('main product: ' + parsed.main_product);
    // segment: "same" or "different" only count with a quote found in the data (fail safe: otherwise unclear)
    const jf = String(parsed.job_focus || '').toLowerCase();
    job_focus = ['core', 'major_module', 'minor_feature'].includes(jf) ? jf : 'unknown';

    const seg = String(parsed.segment_match || '').toLowerCase();
    const basis = String(parsed.segment_basis || '').toLowerCase();
    const segQuoteOk = quoteOk(parsed.segment_quote, c.judge_text);
    // the analysed company's customer size counts only if its profile states it
    const ownSizeKnown = /^buyer_company_size:/m.test(String(c.profile_text || ''));
    let segNote = '';
    if (seg === 'same' || seg === 'different') {
      if (!segQuoteOk) segNote = '[' + seg + ' not used: quote not found in the data]';
      else if (seg === 'different' && basis !== 'buyer_type' && !ownSizeKnown) segNote = '[different not used: based on size, but the analysed company does not state its customer size]';
      else segment_match = seg;
    }
    segment_note = [parsed.segment_reason || '', parsed.segment_quote ? '"' + parsed.segment_quote + '"' : '', segNote]
      .filter(Boolean).join(' ');
    const smj = String(parsed.same_main_job || '').toLowerCase();
    var same_main_job = ['yes', 'partly', 'no'].includes(smj) ? smj : 'partly';

    var rivalryMovedToSubstitute = null;
    const byForce = {};
    for (const j of parsed.judgements || []) byForce[String(j.force).toLowerCase()] = j;

    for (const f of forces) {
      const j = byForce[f];
      if (!j) { verdicts[f] = 'unsure'; reasons.push(f + ': unsure - no judgement returned'); continue; }
      let v = cleanVerdict(j.verdict);
      let note = '';
      if (v === 'true') {
        if (quoteOk(j.based_on, c.judge_text)) { if (!judge_quote) judge_quote = String(j.based_on); }
        else { v = 'unsure'; note = ' [quote not found in the data]'; }
      }
      // rule in code: a direct rival must have the SAME main product, not just one module or use case
      if (f === 'rivalry' && v === 'true' && same_main_job !== 'yes') {
        // the job is real, but only as one module or use case of a broader product = a different kind of solution = substitute
        v = 'false';
        note += ' [not a direct rival: main product match is ' + same_main_job + ', counted as substitute]';
        if (same_main_job === 'partly') rivalryMovedToSubstitute = j.based_on || '';
      }
      verdicts[f] = v;
      reasons.push(f + ': ' + v + ' - ' + (j.reason || '') + note);
    }
  }

  // a rival that was downgraded (module of a broader product) becomes a substitute with the same quote
  if (typeof rivalryMovedToSubstitute === 'string' && verdicts.substitute !== 'true') {
    verdicts.substitute = 'true';
    reasons.push('substitute: true - moved from rivalry (module or use case of a broader product)');
    if (!judge_quote && rivalryMovedToSubstitute) judge_quote = rivalryMovedToSubstitute;
  }
  // rivalry and substitute exclude each other: same main product = rivalry, otherwise substitute
  if (verdicts.rivalry === 'true' && verdicts.substitute === 'true') {
    verdicts.substitute = 'false';
    reasons.push('substitute: set to false - same main product, counted as rivalry');
  }
  const vals = Object.values(verdicts);
  let verdict;
  if (buyer === 'no') verdict = 'false';
  else if (vals.includes('true')) verdict = (buyer === 'yes' || !STRICT) ? 'true' : 'unsure';
  else if (vals.includes('unsure')) verdict = 'unsure';
  else verdict = 'false';
  const status = { true: 'verified', unsure: 'unsure', false: 'rejected' }[verdict];

  const out = { ...c };
  // forces the company really belongs to after judging (true or unsure)
  const judged = FORCES.filter(f => verdicts[f] === 'true' || verdicts[f] === 'unsure');
  if (judged.length) { out.forces_text = judged.join(', '); out.force_count = judged.length; }
  delete out.judge_text;
  delete out.profile_text;
  Object.assign(out, {
    buyer_match: buyer,
    business_type,
    verdict,
    verdict_rivalry: verdicts.rivalry || null,
    verdict_substitute: verdicts.substitute || null,
    verdict_new_entrant: verdicts.new_entrant || null,
    judge_reasons: reasons.join('\n'),
    judge_quote: judge_quote || null,
    segment_match,
    segment_note: segment_note || null,
    job_focus,
    status
  });
  // drop empty values so Airtable does not fail on empty single-selects
  for (const k of Object.keys(out)) if (out[k] === null || out[k] === undefined || out[k] === '') delete out[k];
  return { json: out };
});

// Competitor row: exactly the columns of the Supabase table, the SAME keys in every row
// (the Supabase node inserts all rows in one request; Supabase rejects rows with different keys)
const COLS = ['name', 'domain', 'run_id', 'analysed_domain', 'forces_text', 'force_count', 'display_group', 'hits',
  'what_they_do', 'evidence_text', 'recent_moves_text', 'any_direct', 'from_own_site', 'needs_domain'];
const flat = v => Array.isArray(v) ? v.join(', ') : (v && typeof v === 'object') ? JSON.stringify(v) : v;
return $input.all().map(i => {
  const o = { approved: false, status: 'candidate' };
  for (const k of COLS) {
    const v = i.json[k];
    o[k] = (v === undefined || v === null || v === '') ? null : flat(v);
  }
  return { json: o };
});

// Update row: id + only the table columns that have a value (Apollo misses stay untouched)
const COLS = ['needs_domain', 'apollo_id', 'apollo_name', 'apollo_description', 'website_url', 'logo_url', 'hq_city',
  'keywords_text', 'industry', 'headcount_growth_6m', 'headcount_growth_12m', 'headcount_growth_24m', 'sales_headcount',
  'engineering_headcount', 'funding_total_usd', 'last_funding_stage', 'funding_rounds_text', 'revenue', 'parent_company',
  'public_ticker', 'hq_country', 'founded_year', 'funding_total', 'linkedin_url', 'crunchbase_url', 'enrich_note',
  'employees', 'domain', 'verdict', 'verdict_rivalry', 'verdict_substitute', 'verdict_new_entrant', 'buyer_match',
  'judge_reasons', 'status', 'business_type', 'judge_quote', 'forces_text', 'force_count', 'segment_match',
  'segment_note', 'job_focus'];
const flat = v => Array.isArray(v) ? v.join(', ') : (v && typeof v === 'object') ? JSON.stringify(v) : v;
return $input.all().map(i => {
  const j = i.json;
  const o = { id: j.id, enriched: !!j.apollo_id };
  for (const k of COLS) {
    const v = j[k];
    if (v !== undefined && v !== null && v !== '') o[k] = flat(v);
  }
  if (j.last_funding_date) o.last_funding_date = new Date(j.last_funding_date).toISOString();
  return { json: o };
});
